import {
    addEventListener,
    clamp,
    classNames,
    createElement,
    getEl,
    getLeadingZeroNum,
    getParsedDate,
    isSameDate,
    setAttribute,
    getWordBoundaryRegExp, 
    getDayPeriodFromHours24,
} from './common/utils';
import consts from './common/consts';
import  { DatepickerOptions } from './Default';

import './DatepickerTime.scss';

interface DatepickerTimeArgs {
    opts: DatepickerOptions;
    dp: any; 
}

export default class DatepickerTime {
    opts: DatepickerOptions;
    dp: any;
    ampm: boolean = false;
    
    // Internal state
    _hours: number = 0;
    minutes: number = 0;
    displayHours: number = 0;
    dayPeriod: string = '';

    // Min/Max constraints
    minHours: number = 0;
    maxHours: number = 23;
    minMinutes: number = 0;
    maxMinutes: number = 59;

    // DOM Elements
    $el!: HTMLElement;
    $ranges!: NodeListOf<HTMLInputElement>;
    $hours!: HTMLInputElement;
    $minutes!: HTMLInputElement;
    $hoursText!: HTMLElement;
    $minutesText!: HTMLElement;
    $ampm!: HTMLElement;

    constructor({ opts, dp }: DatepickerTimeArgs) {
        this.opts = opts;
        this.dp = dp;
        // Check BOTH the localized format and the passed options
        const timeFormat = this.dp.locale.timeFormat || this.opts.timeFormat || '';
        // const { timeFormat } = this.dp.locale;

        if (timeFormat && (timeFormat.match(getWordBoundaryRegExp('h')) || timeFormat.match(getWordBoundaryRegExp('hh')))) {
            this.ampm = true;
        }

        this.init();
    }

    init(): void {
        this.setTime(this.dp.lastSelectedDate || this.dp.viewDate);
        this.createElement();
        this.buildHtml();
        this.defineDOM();
        this.render();

        this.bindDatepickerEvents();
        this.bindDOMEvents();
    }

    bindDatepickerEvents(): void {
        this.dp.on(consts.eventChangeSelectedDate, this.onChangeSelectedDate);
        this.dp.on(consts.eventChangeLastSelectedDate, this.onChangeLastSelectedDate);
    }

    bindDOMEvents(): void {
        let changeEvent: string = 'input';
        if (navigator.userAgent.match(/trident/gi)) {
            changeEvent = 'change';
        }

        addEventListener(this.$ranges, changeEvent, this.onChangeInputRange as EventListener);
        addEventListener(this.$ranges, 'mouseenter', this.onMouseEnterLeave as EventListener);
        addEventListener(this.$ranges, 'mouseleave', this.onMouseEnterLeave as EventListener);
        addEventListener(this.$ranges, 'focus', this.onFocus);
        addEventListener(this.$ranges, 'mousedown', this.onFocus);
        addEventListener(this.$ranges, 'blur', this.onBlur);
    }

    createElement(): void {
        this.$el = createElement({
            className: classNames('datepicker-time', { '-am-pm-': this.ampm })
        });
    }

    destroy(): void {
        this.dp.off(consts.eventChangeSelectedDate, this.onChangeSelectedDate);
        this.dp.off(consts.eventChangeLastSelectedDate, this.onChangeLastSelectedDate);
        this.$el.parentNode?.removeChild(this.$el);
    }

    buildHtml(): void {
        const {
            ampm, hours, displayHours, minutes, minHours, minMinutes, maxHours, maxMinutes, dayPeriod,
            opts: { hoursStep, minutesStep }
        } = this;

        this.$el.innerHTML = `
            <div class="datepicker-time--current">
                <span class="datepicker-time--current-hours">${getLeadingZeroNum(displayHours)}</span>
                <span class="datepicker-time--current-colon">:</span>
                <span class="datepicker-time--current-minutes">${getLeadingZeroNum(minutes)}</span>
                ${ampm ? `<span class='datepicker-time--current-ampm'>${dayPeriod}</span>` : ''}
            </div>
            <div class="datepicker-time--sliders">
                <div class="datepicker-time--row">
                    <input type="range" name="hours" value="${hours}" min="${minHours}" max="${maxHours}" step="${hoursStep}"/>
                </div>
                <div class="datepicker-time--row">
                    <input type="range" name="minutes" value="${minutes}" min="${minMinutes}" max="${maxMinutes}" step="${minutesStep}"/>
                </div>
            </div>`;
    }

    defineDOM(): void {
        const getElWithContext = (selector: string) => getEl(selector, this.$el);

        this.$ranges = this.$el.querySelectorAll('[type="range"]');
        this.$hours = getElWithContext('[name="hours"]') as HTMLInputElement;
        this.$minutes = getElWithContext('[name="minutes"]') as HTMLInputElement;
        this.$hoursText = getElWithContext('.datepicker-time--current-hours') as HTMLElement;
        this.$minutesText = getElWithContext('.datepicker-time--current-minutes') as HTMLElement;
        this.$ampm = getElWithContext('.datepicker-time--current-ampm') as HTMLElement;
    }

    setTime(date: Date): void {
        this.setMinMaxTime(date);
        this.setCurrentTime(date);
    }

    addTimeToDate(date: Date | undefined): void {
        if (!date) return;
        date.setHours(this.hours);
        date.setMinutes(this.minutes);
    }

    setMinMaxTime(date: Date): void {
        this.setMinMaxTimeFromOptions();

        if (date) {
            const { minDate, maxDate } = this.dp;
            if (minDate && isSameDate(date, minDate)) {
                this.setMinTimeFromMinDate(minDate);
            }
            if (maxDate && isSameDate(date, maxDate)) {
                this.setMaxTimeFromMaxDate(maxDate);
            }
        }
    }

    setCurrentTime(date: Date | false): void {
        const { hours, minutes } = date ? getParsedDate(date) : { hours: this.hours, minutes: this.minutes };

        this.hours = clamp(hours, this.minHours, this.maxHours);
        this.minutes = clamp(minutes, this.minMinutes, this.maxMinutes);
    }

    setMinMaxTimeFromOptions(): void {
        const maxHoursPossible = 23;
        const maxMinutesPossible = 59;
        const { minHours = 0, minMinutes = 0, maxHours = 23, maxMinutes = 59 } = this.opts;

        this.minHours = clamp(minHours, 0, maxHoursPossible);
        this.minMinutes = clamp(minMinutes, 0, maxMinutesPossible);
        this.maxHours = clamp(maxHours, 0, maxHoursPossible);
        this.maxMinutes = clamp(maxMinutes, 0, maxMinutesPossible);
    }

    setMinTimeFromMinDate(date: Date): void {
        const { lastSelectedDate } = this.dp;

        this.minHours = date.getHours();

        if (lastSelectedDate && lastSelectedDate.getHours() > date.getHours()) {
            this.minMinutes = this.opts.minMinutes || 0;
        } else {
            this.minMinutes = date.getMinutes();
        }
    }

    setMaxTimeFromMaxDate(date: Date): void {
        const { lastSelectedDate } = this.dp;

        this.maxHours = date.getHours();

        if (lastSelectedDate && lastSelectedDate.getHours() < date.getHours()) {
            this.maxMinutes = this.opts.maxMinutes || 59;
        } else {
            this.maxMinutes = date.getMinutes();
        }
    }

    updateSliders(): void {
        setAttribute(this.$hours, {
            min: this.minHours,
            max: this.maxHours
        });
        this.$hours.value = this.hours.toString();

        setAttribute(this.$minutes, {
            min: this.minMinutes,
            max: this.maxMinutes
        });
        this.$minutes.value = this.minutes.toString();
    }

    
    updateText(): void {
        this.$hoursText.innerHTML =`${getLeadingZeroNum(this.displayHours)}`;;
        this.$minutesText.innerHTML = `${getLeadingZeroNum(this.minutes)}`;;

        if (this.ampm && this.$ampm) {
            this.$ampm.innerHTML = this.dayPeriod;
        }
    }
    

    toggleTimepickerIsActive = (value: boolean): void => {
        this.dp.timepickerIsActive = value;
    }

    onChangeSelectedDate = ({ date, updateTime = false }: { date: Date, updateTime?: boolean }): void => {
        if (!date) return;

        this.setMinMaxTime(date);
        this.setCurrentTime(updateTime ? date : false);
        this.addTimeToDate(date);

        date.setHours(this.hours);
        date.setMinutes(this.minutes);
    }

    onChangeLastSelectedDate = (date: Date): void => {
        if (!date) return;

        this.setTime(date);
        this.render();
    }

    onChangeInputRange = (e: Event): void => {
        const $target = e.target as HTMLInputElement;
        const name = $target.getAttribute('name') as 'hours' | 'minutes';

        if (name === 'hours') {
            this.hours = parseInt($target.value);
        } else {
            this.minutes = parseInt($target.value);
        }

        this.updateText();

        // IMPORTANT: Update the actual date object in the main instance
        if (this.dp.lastSelectedDate) {
            this.dp.lastSelectedDate.setHours(this.hours);
            this.dp.lastSelectedDate.setMinutes(this.minutes);
            this.dp.lastSelectedDate.setSeconds(0); 
        }

        this.dp.trigger(consts.eventChangeTime, {
            hours: this.hours,
            minutes: this.minutes
        });
    }

    onMouseEnterLeave = (e: MouseEvent): void => {
        const target = e.target as HTMLInputElement;
        const name = target.getAttribute('name');
        let $el = this.$minutesText;

        if (name === 'hours') {
            $el = this.$hoursText;
        }

        $el.classList.toggle('-focus-');
    }

    onFocus = (): void => {
        this.toggleTimepickerIsActive(true);
    }

    onBlur = (): void => {
        this.toggleTimepickerIsActive(false);
    }

    set hours(val: number | string) {
        const numericVal = typeof val === 'string' ? parseInt(val) : val;
        this._hours = numericVal;

        const { hours, dayPeriod } = getDayPeriodFromHours24(numericVal);

        this.displayHours = this.ampm ? hours : numericVal;
        this.dayPeriod = dayPeriod;
    }

    get hours(): number {
        return this._hours;
    }

    render(): void {
        this.updateSliders();
        this.updateText();
    }
}